package app;

import app.repositories.MemoryPatientRepository;
import app.repositories.MemoryRoomRepository;
import app.repositories.PatientRepository;
import app.repositories.RoomRepository;
import java.util.function.Function;

/** The in-memory repositories, for tests and for trying the services without a database. */
public class MemoryUnitOfWork implements UnitOfWork {
    private final PatientRepository patients = new MemoryPatientRepository();
    private final RoomRepository rooms = new MemoryRoomRepository();

    @Override
    public PatientRepository patients() {
        return patients;
    }

    @Override
    public RoomRepository rooms() {
        return rooms;
    }

    /** Memory has no transactions: changes are kept as they are made. */
    @Override
    public <T> T transaction(Function<UnitOfWork, T> work) {
        return work.apply(this);
    }
}

