package app;

import app.repositories.PatientRepository;
import app.repositories.RoomRepository;
import app.repositories.MongoPatientRepository;
import app.repositories.MongoRoomRepository;
import java.util.function.Function;
import org.springframework.data.mongodb.core.MongoTemplate;

/** The repositories over one MongoTemplate. */
public class MongoUnitOfWork implements UnitOfWork {
    private final MongoTemplate mongo;
    private final PatientRepository patients;
    private final RoomRepository rooms;

    public MongoUnitOfWork(MongoTemplate mongo) {
        this.mongo = mongo;
        this.patients = new MongoPatientRepository(mongo);
        this.rooms = new MongoRoomRepository(mongo);
    }

    public MongoTemplate mongo() {
        return mongo;
    }

    @Override
    public PatientRepository patients() {
        return patients;
    }

    @Override
    public RoomRepository rooms() {
        return rooms;
    }

    @Override
    public <T> T transaction(Function<UnitOfWork, T> work) {
        return work.apply(this);
    }
}

