package app.repositories;

import app.common.Page;
import app.entities.Patient;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.stream.Stream;
import org.bson.types.ObjectId;

/** Keeps patients rows in memory, for tests and for trying the services without a database. */
public class MemoryPatientRepository implements PatientRepository {
    private final Map<List<Object>, Patient> rows = new LinkedHashMap<>();

    /** The key of a row, as a list of its key values. */
    private static List<Object> keyOf(Patient row) {
        List<Object> key = new ArrayList<>();
        key.add(row.getId());
        return key;
    }

    /** Orders two keys value by value. */
    @SuppressWarnings({"unchecked", "rawtypes"})
    private static int compareKeys(List<Object> a, List<Object> b) {
        for (int index = 0; index < a.size(); index++) {
            int order = ((Comparable) a.get(index)).compareTo(b.get(index));
            if (order != 0) return order;
        }
        return 0;
    }

    private Stream<Patient> visible() {
        return rows.values().stream().filter((row) -> true).sorted(Comparator.comparing(MemoryPatientRepository::keyOf, MemoryPatientRepository::compareKeys));
    }

    @Override
    public Optional<Patient> findById(String id) {
        return visible().filter((row) -> Objects.equals(row.getId(), id)).findFirst();
    }

    @Override
    public Page<Patient> list(int offset, int limit) {
        List<Patient> rows = visible().toList();
        return new Page<>(rows.stream().skip(offset).limit(limit).toList(), rows.size(), offset, limit);
    }

    @Override
    public Optional<Patient> findByDocument(String document) {
        return visible().filter((row) -> Objects.equals(row.getDocument(), document)).findFirst();
    }

    @Override
    public List<Patient> findAllByBirth(Instant birth) {
        return visible().filter((row) -> Objects.equals(row.getBirth(), birth)).toList();
    }

    @Override
    public Patient insert(Patient entity) {
        if (entity.getId() == null) entity.setId(new ObjectId().toHexString());
        rows.put(keyOf(entity), entity);
        return entity;
    }

    @Override
    public Patient update(Patient entity) {
        rows.put(keyOf(entity), entity);
        return entity;
    }

    @Override
    public void delete(Patient entity) {
        rows.remove(keyOf(entity));
    }

    @Override
    public Optional<Patient> addContact(String id, Patient.Contact contact) {
        Optional<Patient> found = visible().filter((row) -> Objects.equals(row.getId(), id)).findFirst();
        found.ifPresent((row) -> {
            List<Patient.Contact> items = row.getContacts() == null ? new ArrayList<>() : new ArrayList<>(row.getContacts());
            items.add(contact);
            row.setContacts(items);
            row.setVersion((row.getVersion() == null ? 0 : row.getVersion()) + 1);
        });
        return found;
    }

    @Override
    public Optional<Patient> removeContact(String id, int position, int size) {
        Optional<Patient> found = visible().filter((row) -> Objects.equals(row.getId(), id)).findFirst();
        if (found.isPresent() && (found.get().getContacts() == null ? 0 : found.get().getContacts().size()) != size) return Optional.empty();
        found.ifPresent((row) -> {
            List<Patient.Contact> items = row.getContacts() == null ? new ArrayList<>() : new ArrayList<>(row.getContacts());
            items.remove(position);
            row.setContacts(items);
            row.setVersion((row.getVersion() == null ? 0 : row.getVersion()) + 1);
        });
        return found;
    }
}

