package app.repositories;

import app.Documents;
import app.common.Page;
import app.entities.Patient;
import com.mongodb.client.model.Filters;
import com.mongodb.client.model.FindOneAndUpdateOptions;
import com.mongodb.client.model.ReturnDocument;
import java.time.Instant;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.WeakHashMap;
import org.bson.Document;
import org.bson.types.ObjectId;
import org.springframework.dao.DataAccessException;
import org.springframework.data.domain.Sort;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.query.Criteria;
import org.springframework.data.mongodb.core.query.Query;

/** Keeps patients documents in the database, through a MongoTemplate. Every write is stored at once. */
public class MongoPatientRepository implements PatientRepository {
    /** The document each entity was read from: a change writes only the fields that differ */
    private static final Map<Patient, Document> LOADED = Collections.synchronizedMap(new WeakHashMap<>());

    /** The fields a change may write */
    private static final List<String> FIELDS = List.of("name", "birth", "weight", "balance", "document", "photo", "visits", "blood", "contacts", "insurance", "version");

    private final MongoTemplate mongo;

    public MongoPatientRepository(MongoTemplate mongo) {
        this.mongo = mongo;
    }

    @Override
    public Optional<Patient> findById(String id) {
        Patient found = mongo.findOne(Query.query(Criteria.where("id").is(id)), Patient.class);
        return Optional.ofNullable(found == null ? null : loaded(found));
    }

    @Override
    public Page<Patient> list(int offset, int limit) {
        List<Patient> items = mongo.find(new Query().with(Sort.by("id")).skip(offset).limit(limit), Patient.class).stream().map(this::loaded).toList();
        return new Page<>(items, mongo.count(new Query(), Patient.class), offset, limit);
    }

    @Override
    public Optional<Patient> findByDocument(String document) {
        Patient found = mongo.findOne(Query.query(Criteria.where("document").is(document)), Patient.class);
        return Optional.ofNullable(found == null ? null : loaded(found));
    }

    @Override
    public List<Patient> findAllByBirth(Instant birth) {
        return mongo.find(Query.query(Criteria.where("birth").is(birth)).with(Sort.by("id")), Patient.class).stream().map(this::loaded).toList();
    }

    @Override
    public Patient insert(Patient entity) {
        try {
            mongo.insert(entity);
        } catch (DataAccessException error) {
            throw Documents.refusal("Patient", error);
        }
        return loaded(entity);
    }

    @Override
    public Patient update(Patient entity) {
        Document now = Documents.of(mongo, entity);
        Document changes = Documents.changes(LOADED.get(entity), now, FIELDS);
        try {
            if (!changes.isEmpty()) mongo.execute(Patient.class, (collection) -> collection.updateOne(Filters.eq("_id", now.get("_id")), changes));
        } catch (DataAccessException error) {
            throw Documents.refusal("Patient", error);
        }
        return loaded(entity);
    }

    @Override
    public void delete(Patient entity) {
        try {
            mongo.remove(Query.query(Criteria.where("id").is(entity.getId())), Patient.class);
        } catch (DataAccessException error) {
            throw Documents.refusal("Patient", error);
        }
    }

    @Override
    public Optional<Patient> addContact(String id, Patient.Contact contact) {
        if (!ObjectId.isValid(id)) return Optional.empty();
        Document change = new Document("$push", new Document("contacts", Documents.of(mongo, contact))).append("$inc", new Document("version", 1));
        Document filter = new Document("_id", new ObjectId(id));
        FindOneAndUpdateOptions after = new FindOneAndUpdateOptions().returnDocument(ReturnDocument.AFTER);
        Document changed;
        try {
            changed = mongo.execute(Patient.class, (collection) -> collection.findOneAndUpdate(filter, change, after));
        } catch (DataAccessException error) {
            throw Documents.refusal("Patient", error);
        }
        return Optional.ofNullable(changed).map((document) -> loaded(mongo.getConverter().read(Patient.class, document)));
    }

    @Override
    public Optional<Patient> removeContact(String id, int position, int size) {
        if (!ObjectId.isValid(id)) return Optional.empty();
        Document head = new Document("$slice", List.of("$contacts", position));
        Document tail = new Document("$slice", List.of("$contacts", position + 1, Math.max(size, 1)));
        List<Document> change = List.of(new Document("$set", new Document("contacts", new Document("$concatArrays", List.of(head, tail))).append("version", new Document("$add", List.of("$version", 1)))));
        Document filter = new Document("_id", new ObjectId(id)).append("contacts", new Document("$size", size));
        FindOneAndUpdateOptions after = new FindOneAndUpdateOptions().returnDocument(ReturnDocument.AFTER);
        Document changed;
        try {
            changed = mongo.execute(Patient.class, (collection) -> collection.findOneAndUpdate(filter, change, after));
        } catch (DataAccessException error) {
            throw Documents.refusal("Patient", error);
        }
        return Optional.ofNullable(changed).map((document) -> loaded(mongo.getConverter().read(Patient.class, document)));
    }

    /** The same entity, with what it is stored as kept to tell its changes. */
    private Patient loaded(Patient entity) {
        LOADED.put(entity, Documents.of(mongo, entity));
        return entity;
    }
}

