package app.services;

import app.UnitOfWork;
import app.common.Page;
import app.dtos.PatientCreate;
import app.dtos.PatientRead;
import app.dtos.PatientUpdate;
import app.entities.Patient;
import app.errors.ConflictException;
import app.errors.FieldError;
import app.errors.NotFoundException;
import app.errors.ValidationFailedException;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.stream.Stream;

/** Operations on patients. Repositories commit every write. */
public class PatientService {
    private final UnitOfWork uow;

    public PatientService(UnitOfWork uow) {
        this.uow = uow;
    }

    /** Checks the values against the rules of the "patients" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private void validate(UnitOfWork uow, Map<String, Object> values, Patient current) {
        boolean creating = current == null;
        List<FieldError> errors = new ArrayList<>();
        {
            Object value = values.get("name");
            if (value == null) {
                if (creating || values.containsKey("name")) errors.add(new FieldError("name", "is required"));
            } else {
                if (value instanceof String text && text.length() > 80) errors.add(new FieldError("name", "is longer than 80 characters"));
                if (!(String.valueOf(value).length() >= 2)) errors.add(new FieldError("name", "must have >= 2 characters"));
            }
        }
        {
            Object value = values.get("birth");
            if (value == null) {
                if (creating || values.containsKey("birth")) errors.add(new FieldError("birth", "is required"));
            }
        }
        {
            Object value = values.get("visits");
            if (value == null) {
                if (creating || values.containsKey("visits")) errors.add(new FieldError("visits", "is required"));
            } else {
                if (!(number(value).compareTo(new BigDecimal("0")) >= 0)) errors.add(new FieldError("visits", "must be >= 0"));
            }
        }
        {
            Object value = values.get("blood");
            if (value != null) {
                if (!List.of("A", "B", "O").contains(String.valueOf(value))) errors.add(new FieldError("blood", "must be one of: A, B, O"));
            }
        }
        {
            Object value = values.get("contacts");
            if (value == null) {
                if (creating || values.containsKey("contacts")) errors.add(new FieldError("contacts", "is required"));
            } else {
                @SuppressWarnings("unchecked")
                List<Patient.Contact> document = (List<Patient.Contact>) value;
                if (document != null) {
                    for (int i0 = 0; i0 < document.size(); i0++) {
                        if (document.get(i0) == null) errors.add(new FieldError("contacts" + "." + i0, "is required"));
                        else checkContact(document.get(i0), "contacts" + "." + i0, errors);
                    }
                }
            }
        }
        {
            Object value = values.get("insurance");
            if (value != null) {
                Patient.Insurance document = (Patient.Insurance) value;
                if (document != null) checkInsurance(document, "insurance", errors);
            }
        }
        if (!errors.isEmpty()) throw new ValidationFailedException("Patient", errors);
    }

    /** A number of any type, to compare it. */
    private static BigDecimal number(Object value) {
        return new BigDecimal(String.valueOf(value));
    }

    /** Values that must be unique are not taken by another row. */
    private void checkUnique(UnitOfWork uow, Map<String, Object> values, Patient current) {
        {
            String document = (String) (values.containsKey("document") ? values.get("document") : current == null ? null : current.getDocument());
            if (document != null) {
                Optional<Patient> other = uow.patients().findByDocument(document);
                if (other.isPresent() && (current == null || !Objects.equals(other.get().getId(), current.getId())))
                    throw new ConflictException("Patient", "document is already taken", List.of("document"));
            }
        }
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private void check(UnitOfWork uow, Map<String, Object> values, Patient current) {
        validate(uow, values, current);
        checkUnique(uow, values, current);
    }

    /** Sets the given values on the entity. */
    @SuppressWarnings("unchecked")
    private static void apply(Patient entity, Map<String, Object> values) {
        if (values.containsKey("name")) entity.setName((String) values.get("name"));
        if (values.containsKey("birth")) entity.setBirth((Instant) values.get("birth"));
        if (values.containsKey("weight")) entity.setWeight((Double) values.get("weight"));
        if (values.containsKey("balance")) entity.setBalance((BigDecimal) values.get("balance"));
        if (values.containsKey("document")) entity.setDocument((String) values.get("document"));
        if (values.containsKey("photo")) entity.setPhoto((byte[]) values.get("photo"));
        if (values.containsKey("visits")) entity.setVisits((Integer) values.get("visits"));
        if (values.containsKey("blood")) entity.setBlood((String) values.get("blood"));
        if (values.containsKey("contacts")) entity.setContacts((List<Patient.Contact>) values.get("contacts"));
        if (values.containsKey("insurance")) entity.setInsurance((Patient.Insurance) values.get("insurance"));
        if (values.containsKey("version")) entity.setVersion((Integer) values.get("version"));
    }

    /** The Patient with this key; NotFoundException when there is none. */
    private Patient find(UnitOfWork uow, String id) {
        return uow.patients().findById(id).orElseThrow(() -> new NotFoundException("Patient", id));
    }

    /** The Patient as services return it. */
    private static PatientRead read(Patient entity) {
        return new PatientRead(entity.getId(), entity.getName(), entity.getBirth(), entity.getWeight(), entity.getBalance(), entity.getDocument(), entity.getPhoto(), entity.getVisits(), entity.getBlood(), entity.getContacts(), entity.getInsurance(), entity.getVersion());
    }

    /** The values an update gives, by field. */
    private static Map<String, Object> given(PatientUpdate changes) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (changes.name() != null) values.put("name", changes.name().orElse(null));
        if (changes.birth() != null) values.put("birth", changes.birth().orElse(null));
        if (changes.weight() != null) values.put("weight", changes.weight().orElse(null));
        if (changes.balance() != null) values.put("balance", changes.balance().orElse(null));
        if (changes.document() != null) values.put("document", changes.document().orElse(null));
        if (changes.photo() != null) values.put("photo", changes.photo().orElse(null));
        if (changes.visits() != null) values.put("visits", changes.visits().orElse(null));
        if (changes.blood() != null) values.put("blood", changes.blood().orElse(null));
        if (changes.contacts() != null) values.put("contacts", changes.contacts().orElse(null));
        if (changes.insurance() != null) values.put("insurance", changes.insurance().orElse(null));
        if (changes.version() != null) values.put("version", changes.version().orElse(null));
        return values;
    }

    /** What a Contact does not follow of its rules, each with the path of its field. */
    private static void checkContact(Patient.Contact value, String path, List<FieldError> errors) {
        if (value.getKind() == null) errors.add(new FieldError(path + ".kind", "is required"));
        if (value.getKind() != null && !List.of("phone", "email").contains(value.getKind())) errors.add(new FieldError(path + ".kind", "must be one of: phone, email"));
        if (value.getValue() == null) errors.add(new FieldError(path + ".value", "is required"));
    }

    /** What a Insurance does not follow of its rules, each with the path of its field. */
    private static void checkInsurance(Patient.Insurance value, String path, List<FieldError> errors) {
    }

    /** Stores a new Patient after checking it. */
    public PatientRead createPatient(PatientCreate data) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (data.name() != null) values.put("name", data.name());
        if (data.birth() != null) values.put("birth", data.birth());
        if (data.weight() != null) values.put("weight", data.weight());
        if (data.balance() != null) values.put("balance", data.balance());
        if (data.document() != null) values.put("document", data.document());
        if (data.photo() != null) values.put("photo", data.photo());
        if (data.visits() != null) values.put("visits", data.visits());
        if (data.blood() != null) values.put("blood", data.blood());
        if (data.contacts() != null) values.put("contacts", data.contacts());
        if (data.insurance() != null) values.put("insurance", data.insurance());
        if (data.version() != null) values.put("version", data.version());
        return uow.transaction((uow) -> {
            check(uow, values, null);
            Patient entity = new Patient();
            apply(entity, values);
            return read(uow.patients().insert(entity));
        });
    }

    /** The Patient with this key; NotFoundException when there is none. */
    public PatientRead getPatient(String id) {
        return read(find(uow, id));
    }

    /** A page of patients, by primary key. */
    public Page<PatientRead> listPatients(int offset, int limit) {
        return uow.patients().list(offset, limit).map(PatientService::read);
    }

    /** Changes the given values of a Patient, read at version. */
    public PatientRead updatePatient(String id, PatientUpdate changes, Integer version) {
        Map<String, Object> values = given(changes);
        return uow.transaction((uow) -> {
            Patient current = find(uow, id);
            if (!Objects.equals(current.getVersion(), version))
                throw new ConflictException("Patient", "was changed by someone else since it was read", List.of("version"));
            check(uow, values, current);
            apply(current, values);
            current.setVersion(version + 1);
            return read(uow.patients().update(current));
        });
    }

    /** Deletes a Patient. */
    public void deletePatient(String id, Integer version) {
        uow.transaction((uow) -> {
            Patient current = find(uow, id);
            if (!Objects.equals(current.getVersion(), version))
                throw new ConflictException("Patient", "was changed by someone else since it was read", List.of("version"));
            uow.patients().delete(current);
            return null;
        });
    }

    /** The Patient with this document, if there is one. */
    public Optional<PatientRead> findPatientByDocument(String document) {
        return uow.patients().findByDocument(document).map(PatientService::read);
    }

    /** Adds an item to contacts, read at version. */
    public PatientRead addContact(String id, Patient.Contact contact, Integer version) {
        List<FieldError> errors = new ArrayList<>();
        checkContact(contact, "contacts", errors);
        if (!errors.isEmpty()) throw new ValidationFailedException("Patient", errors);
        return uow.transaction((uow) -> {
            Patient current = find(uow, id);
            if (!Objects.equals(current.getVersion(), version))
                throw new ConflictException("Patient", "was changed by someone else since it was read", List.of("version"));
            return read(uow.patients().addContact(id, contact).orElseThrow(() -> new NotFoundException("Patient", id)));
        });
    }

    /** Removes an item from contacts, by its position, read at version. */
    public PatientRead removeContact(String id, int position, Integer version) {
        return uow.transaction((uow) -> {
            Patient current = find(uow, id);
            if (!Objects.equals(current.getVersion(), version))
                throw new ConflictException("Patient", "was changed by someone else since it was read", List.of("version"));
            if (current.getContacts() == null || position < 0 || position >= current.getContacts().size()) throw new NotFoundException("Contact", position);
            return read(uow.patients().removeContact(id, position, current.getContacts().size()).orElseThrow(() -> new ConflictException("Patient", "was changed by someone else since it was read", List.of("contacts"))));
        });
    }
}

