import app.errors.ValidationFailedException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Operations on rooms. Repositories commit every write. */
public class RoomService {
    private final UnitOfWork uow;

    public RoomService(UnitOfWork uow) {
        this.uow = uow;
    }

    /** Checks the values against the rules of the "rooms" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private void validate(UnitOfWork uow, Map<String, Object> values, Room current) {
        boolean creating = current == null;
        List<FieldError> errors = new ArrayList<>();
        {
            Object value = values.get("code");
            if (value == null) {
                if (creating || values.containsKey("code")) errors.add(new FieldError("code", "is required"));
            }
        }
        if (!errors.isEmpty()) throw new ValidationFailedException("Room", errors);
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private void check(UnitOfWork uow, Map<String, Object> values, Room current) {
        validate(uow, values, current);
    }

    /** Sets the given values on the entity. */
    private static void apply(Room entity, Map<String, Object> values) {
        if (values.containsKey("code")) entity.setCode((String) values.get("code"));
        if (values.containsKey("beds")) entity.setBeds((Long) values.get("beds"));
    }

    /** The Room with this key; NotFoundException when there is none. */
    private Room find(UnitOfWork uow, String id) {
        return uow.rooms().findById(id).orElseThrow(() -> new NotFoundException("Room", id));
    }

    /** The Room as services return it. */
    private static RoomRead read(Room entity) {
        return new RoomRead(entity.getId(), entity.getCode(), entity.getBeds());
    }

    /** The values an update gives, by field. */
    private static Map<String, Object> given(RoomUpdate changes) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (changes.code() != null) values.put("code", changes.code().orElse(null));
        if (changes.beds() != null) values.put("beds", changes.beds().orElse(null));
        return values;
    }

    /** Stores a new Room after checking it. */
    public RoomRead createRoom(RoomCreate data) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (data.code() != null) values.put("code", data.code());
        if (data.beds() != null) values.put("beds", data.beds());
        return uow.transaction((uow) -> {
            check(uow, values, null);
            Room entity = new Room();
            apply(entity, values);
            return read(uow.rooms().insert(entity));
        });
    }

    /** The Room with this key; NotFoundException when there is none. */
    public RoomRead getRoom(String id) {
        return read(find(uow, id));
    }

    /** A page of rooms, by primary key. */
    public Page<RoomRead> listRooms(int offset, int limit) {
        return uow.rooms().list(offset, limit).map(RoomService::read);
    }

    /** Changes the given values of a Room. */
    public RoomRead updateRoom(String id, RoomUpdate changes) {
        Map<String, Object> values = given(changes);
        return uow.transaction((uow) -> {
            Room current = find(uow, id);
            check(uow, values, current);
            apply(current, values);
            return read(uow.rooms().update(current));
        });
    }

    /** Deletes a Room. */
    public void deleteRoom(String id) {
        uow.transaction((uow) -> {
            Room current = find(uow, id);
            uow.rooms().delete(current);
            return null;
        });
    }
}

