package app;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import app.dtos.PatientCreate;
import app.dtos.PatientUpdate;
import app.entities.Patient;
import app.errors.ConflictException;
import app.errors.FieldError;
import app.errors.NotFoundException;
import app.errors.ValidationFailedException;
import app.services.PatientService;
import java.util.List;
import java.util.Optional;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

/** Tests of the "patients" table. */
class PatientTest {
    /** The repositories over the test database, opened empty for every test */
    private MongoUnitOfWork uow;

    @BeforeEach
    void open() {
        uow = new MongoUnitOfWork(TestDatabase.open());
    }

    @Nested
    class Repository {

        @Test
        void isStoredAndReadBack() {
            Patient stored = Factories.addPatient(uow, 1);
            Patient found = uow.patients().findById(stored.getId()).orElseThrow();
            assertEquals(stored.getId(), found.getId());
            if (stored.getDocument() != null) assertTrue(uow.patients().findByDocument(stored.getDocument()).isPresent());
        }

        @Test
        void listsRowsByKey() {
            Factories.addPatient(uow, 1);
            Factories.addPatient(uow, 2);
            var page = uow.patients().list(0, 1);
            assertEquals(2, page.total());
            assertEquals(1, page.items().size());
        }

        @Test
        void addsAndRemovesOneItemOfContacts() {
            Patient stored = Factories.addPatient(uow, 1);
            int before = stored.getContacts() == null ? 0 : stored.getContacts().size();
            Patient.Contact item = Factories.newPatientContact(7);
            Patient added = uow.patients().addContact(stored.getId(), item).orElseThrow();
            assertEquals(before + 1, added.getContacts().size());
            Patient removed = uow.patients().removeContact(stored.getId(), before, added.getContacts().size()).orElseThrow();
            assertEquals(before, removed.getContacts().size());
            assertTrue(uow.patients().removeContact(stored.getId(), 0, before + 5).isEmpty());
        }

        @Test
        void isDeleted() {
            Patient stored = Factories.addPatient(uow, 1);
            uow.patients().delete(stored);
            assertTrue(uow.patients().findById(stored.getId()).isEmpty());
        }
    }

    @Nested
    class PatientServiceTest {
        private final MemoryUnitOfWork uow = new MemoryUnitOfWork();

        @Test
        void createsAValidRow() {
            PatientService service = new PatientService(uow);
            int n = 100;
            Patient row = Factories.newPatient(1);
            var created = service.createPatient(createOf(row));
            var found = service.getPatient(created.id());
            assertEquals(created.id(), found.id());
        }

        @Test
        void refusesAMissingValue() {
            PatientService service = new PatientService(uow);
            int n = 100;
            Patient row = Factories.newPatient(1);
            row.setName(null);
            ValidationFailedException error = assertThrows(ValidationFailedException.class, () -> service.createPatient(createOf(row)));
            assertEquals(List.of("name"), error.getErrors().stream().map(FieldError::field).toList());
        }

        @Test
        void refusesARepeatedUniqueValue() {
            PatientService service = new PatientService(uow);
            int n = 100;
            Patient row = Factories.newPatient(1);
            var first = service.createPatient(createOf(row));
            Patient again = Factories.newPatient(2);
            again.setDocument(first.document());
            assertThrows(ConflictException.class, () -> service.createPatient(createOf(again)));
        }

        @Test
        void keepsItsOwnUniqueValue() {
            PatientService service = new PatientService(uow);
            int n = 100;
            Patient row = Factories.newPatient(1);
            var created = service.createPatient(createOf(row));
            service.updatePatient(created.id(), new PatientUpdate(null, null, null, null, Optional.of(created.document()), null, null, null, null, null, null), created.version());
        }

        @Test
        void saysWhenARowIsMissing() {
            PatientService service = new PatientService(uow);
            assertThrows(NotFoundException.class, () -> service.getPatient("ffffffffffffffffffffffff"));
        }

        @Test
        void addsAndRemovesOneItemOfContacts() {
            PatientService service = new PatientService(uow);
            int n = 100;
            Patient row = Factories.newPatient(1);
            var created = service.createPatient(createOf(row));
            int before = created.contacts() == null ? 0 : created.contacts().size();
            Patient.Contact item = Factories.newPatientContact(7);
            var added = service.addContact(created.id(), item, created.version());
            assertEquals(before + 1, added.contacts().size());
            var removed = service.removeContact(created.id(), before, added.version());
            assertEquals(before, removed.contacts().size());
            assertThrows(NotFoundException.class, () -> service.removeContact(created.id(), 99, removed.version()));
        }

        @Test
        void deletesARow() {
            PatientService service = new PatientService(uow);
            int n = 100;
            Patient row = Factories.newPatient(1);
            var created = service.createPatient(createOf(row));
            service.deletePatient(created.id(), created.version());
            assertThrows(NotFoundException.class, () -> service.getPatient(created.id()));
        }
    }

    /** The create DTO of a row the factories made. */
    private static PatientCreate createOf(Patient row) {
        return new PatientCreate(row.getName(), row.getBirth(), row.getWeight(), row.getBalance(), row.getDocument(), row.getPhoto(), row.getVisits(), row.getBlood(), row.getContacts(), row.getInsurance(), row.getVersion());
    }
}

