            RoomService service = new RoomService(uow);
            assertThrows(NotFoundException.class, () -> service.getRoom("ffffffffffffffffffffffff"));
        }

        @Test
        void changesARow() {
            RoomService service = new RoomService(uow);
            int n = 100;
            Room row = Factories.newRoom(1);
            var created = service.createRoom(createOf(row));
            var updated = service.updateRoom(created.id(), new RoomUpdate(Optional.of("changed"), null));
            assertEquals("changed", updated.code());
        }

        @Test
        void deletesARow() {
            RoomService service = new RoomService(uow);
            int n = 100;
            Room row = Factories.newRoom(1);
            var created = service.createRoom(createOf(row));
            service.deleteRoom(created.id());
            assertThrows(NotFoundException.class, () -> service.getRoom(created.id()));
        }
    }

    /** The create DTO of a row the factories made. */
    private static RoomCreate createOf(Room row) {
        return new RoomCreate(row.getCode(), row.getBeds());
    }
